import org.springframework.stereotype.Service;

@Service
public class ContactMessageService {

    private final LinkedList<ContactMessage> messages = new LinkedList<>();

    public synchronized void add(ContactMessage message) {
        messages.addFirst(message);
    }

    public synchronized List<ContactMessage> getMessages() {
        return Collections.unmodifiableList(new LinkedList<>(messages));
    }
}
