+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private final ContactMessageService service;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(ContactMessageService service) {
+        this.service = service;
+
+        H1 heading = new H1("Contact");
+        RouterLink aboutLink = new RouterLink("About", AboutView.class);
+
+        FormLayout formLayout = new FormLayout(nameField, emailField, phoneField, messageField);
+
+        sendButton.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        sendButton.addClickListener(e -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        nameField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        emailField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        phoneField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        messageField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        refreshGrid();
+
+        add(heading, aboutLink, formLayout, sendButton, grid);
+    }
+
+    private void enableSendOnClientEdit(boolean fromClient) {
+        if (fromClient) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+
+        ContactMessage message = new ContactMessage(nameField.getValue().trim(), emailField.getValue().trim(),
+                phoneField.getValue().trim(), messageField.getValue().trim());
+        service.add(message);
+        refreshGrid();
+        clearForm();
+        Notification.show("Message sent");
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        String name = nameField.getValue().trim();
+        if (name.isEmpty()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        } else {
+            nameField.setInvalid(false);
+        }
+
+        String email = emailField.getValue().trim();
+        String phone = phoneField.getValue().trim();
+        if (!email.isEmpty() && isInvalidEmail(email)) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isEmpty() && phone.isEmpty()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            emailField.setInvalid(false);
+        }
+
+        String message = messageField.getValue().trim();
+        if (message.isEmpty()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.length() > 500) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        } else {
+            messageField.setInvalid(false);
+        }
+
+        return valid;
+    }
+
+    private boolean isInvalidEmail(String email) {
+        ValidationResult result = new EmailValidator("invalid").apply(email, new ValueContext());
+        return result.isError();
+    }
+
+    private void clearForm() {
+        nameField.setValue("");
+        emailField.setValue("");
+        phoneField.setValue("");
+        messageField.setValue("");
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(service.getMessages());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty() || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty() || !messageField.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            var action = event.postpone();
+            confirmDiscard(action);
+        }
+    }
+
+    private void confirmDiscard(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.add(new Text("You have unsaved changes. Do you want to discard them?"));
+
+        Button keepEditing = new Button("Keep editing", e -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
