+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+        assertThat(page.url()).contains("/contact");
+        assertThat(name.getValue()).isEqualTo("Jane");
+
+        page.getByRole(AriaRole.LINK, new com.microsoft.playwright.Page.GetByRoleOptions().setName("About")).click();
+        ButtonElement.getByText(page, "Discard").click();
+
+        page.waitForURL(url -> url.contains("/about"));
+        assertThat(page.url()).contains("/about");
+    }
